public List<List<String>> solveNQueens(int n) {
    List<List<String>> res = new ArrayList<>();
    boolean[] cols = new boolean[n];
    boolean[] diag = new boolean[2 * n - 1];   // r + c
    boolean[] anti = new boolean[2 * n - 1];   // r - c + n - 1
    int[] queen = new int[n];                  // queen[r] = column
    backtrack(0, n, cols, diag, anti, queen, res);
    return res;
}

private void backtrack(int r, int n, boolean[] cols, boolean[] diag,
                       boolean[] anti, int[] queen, List<List<String>> res) {
    if (r == n) {
        List<String> board = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            char[] row = new char[n];
            Arrays.fill(row, '.');
            row[queen[i]] = 'Q';
            board.add(new String(row));
        }
        res.add(board);
        return;
    }
    for (int c = 0; c < n; c++) {
        int d = r + c, a = r - c + n - 1;
        if (cols[c] || diag[d] || anti[a]) continue;
        cols[c] = diag[d] = anti[a] = true;
        queen[r] = c;
        backtrack(r + 1, n, cols, diag, anti, queen, res);
        cols[c] = diag[d] = anti[a] = false;
    }
}

public int totalNQueens(int n) {
    return count(0, 0, 0, (1 << n) - 1);
}

private int count(int col, int diag, int anti, int full) {
    if (col == full) return 1;
    int total = 0;
    int free = ~(col | diag | anti) & full;
    while (free != 0) {
        int p = free & -free;      // lowest set bit
        free -= p;
        total += count(col | p, (diag | p) << 1 & full, (anti | p) >> 1, full);
    }
    return total;
}

public void solveSudoku(char[][] board) {
    boolean[][] rows = new boolean[9][9];
    boolean[][] cols = new boolean[9][9];
    boolean[][] boxes = new boolean[9][9];
    for (int i = 0; i < 9; i++)
        for (int j = 0; j < 9; j++)
            if (board[i][j] != '.') {
                int d = board[i][j] - '1';
                rows[i][d] = cols[j][d] = boxes[(i / 3) * 3 + j / 3][d] = true;
            }
    solve(board, 0, 0, rows, cols, boxes);
}

private boolean solve(char[][] b, int r, int c, boolean[][] rows,
                      boolean[][] cols, boolean[][] boxes) {
    if (r == 9) return true;
    int nr = (c == 8) ? r + 1 : r;
    int nc = (c == 8) ? 0 : c + 1;
    if (b[r][c] != '.') return solve(b, nr, nc, rows, cols, boxes);
    int box = (r / 3) * 3 + c / 3;
    for (int d = 0; d < 9; d++) {
        if (rows[r][d] || cols[c][d] || boxes[box][d]) continue;
        b[r][c] = (char) ('1' + d);
        rows[r][d] = cols[c][d] = boxes[box][d] = true;
        if (solve(b, nr, nc, rows, cols, boxes)) return true;
        b[r][c] = '.';
        rows[r][d] = cols[c][d] = boxes[box][d] = false;
    }
    return false;
}

public List<String> findWords(char[][] board, String[] words) {
    TrieNode root = new TrieNode();
    for (String w : words) {
        TrieNode node = root;
        for (char ch : w.toCharArray()) {
            int i = ch - 'a';
            if (node.next[i] == null) node.next[i] = new TrieNode();
            node = node.next[i];
        }
        node.word = w;
    }
    List<String> res = new ArrayList<>();
    for (int i = 0; i < board.length; i++)
        for (int j = 0; j < board[0].length; j++)
            dfs(board, i, j, root, res);
    return res;
}

private void dfs(char[][] board, int i, int j, TrieNode node, List<String> res) {
    char ch = board[i][j];
    if (ch == '#' || node.next[ch - 'a'] == null) return;
    node = node.next[ch - 'a'];
    if (node.word != null) {
        res.add(node.word);
        node.word = null;               // dedupe
    }
    board[i][j] = '#';
    if (i > 0)                     dfs(board, i - 1, j, node, res);
    if (i < board.length - 1)      dfs(board, i + 1, j, node, res);
    if (j > 0)                     dfs(board, i, j - 1, node, res);
    if (j < board[0].length - 1)   dfs(board, i, j + 1, node, res);
    board[i][j] = ch;
}

