public int minCut(String s) {
    int n = s.length();
    boolean[][] pal = new boolean[n][n];
    for (int i = n - 1; i >= 0; i--)
        for (int j = i; j < n; j++)
            if (s.charAt(i) == s.charAt(j) && (j - i < 2 || pal[i + 1][j - 1]))
                pal[i][j] = true;
    int[] dp = new int[n];
    for (int j = 0; j < n; j++) {
        if (pal[0][j]) { dp[j] = 0; continue; }
        int min = j;                 // at most j cuts
        for (int i = 1; i <= j; i++)
            if (pal[i][j]) min = Math.min(min, dp[i - 1] + 1);
        dp[j] = min;
    }
    return dp[n - 1];
}

public List<List<Integer>> permuteUnique(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> res = new ArrayList<>();
    permute(nums, new boolean[nums.length], new ArrayList<>(), res);
    return res;
}
private void permute(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> res) {
    if (cur.size() == nums.length) { res.add(new ArrayList<>(cur)); return; }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) continue;
        used[i] = true; cur.add(nums[i]);
        permute(nums, used, cur, res);
        cur.remove(cur.size() - 1); used[i] = false;
    }
}

public List<List<Integer>> subsetsWithDup(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> res = new ArrayList<>();
    subsets(nums, 0, new ArrayList<>(), res);
    return res;
}
private void subsets(int[] nums, int start, List<Integer> cur, List<List<Integer>> res) {
    res.add(new ArrayList<>(cur));
    for (int i = start; i < nums.length; i++) {
        if (i > start && nums[i] == nums[i - 1]) continue;
        cur.add(nums[i]);
        subsets(nums, i + 1, cur, res);
        cur.remove(cur.size() - 1);
    }
}

public List<List<Integer>> combinationSum2(int[] candidates, int target) {
    Arrays.sort(candidates);
    List<List<Integer>> res = new ArrayList<>();
    combine(candidates, target, 0, new ArrayList<>(), res);
    return res;
}
private void combine(int[] c, int target, int start, List<Integer> cur, List<List<Integer>> res) {
    if (target == 0) { res.add(new ArrayList<>(cur)); return; }
    for (int i = start; i < c.length; i++) {
        if (i > start && c[i] == c[i - 1]) continue;   // skip duplicate
        if (c[i] > target) break;                      // sorted prune
        cur.add(c[i]);
        combine(c, target - c[i], i + 1, cur, res);
        cur.remove(cur.size() - 1);
    }
}

public List<String> addOperators(String num, int target) {
    List<String> res = new ArrayList<>();
    dfs(num, target, 0, 0, 0, "", res);
    return res;
}

private void dfs(String num, int target, int pos, long eval, long prev,
                 String path, List<String> res) {
    if (pos == num.length()) {
        if (eval == target) res.add(path);
        return;
    }
    for (int i = pos; i < num.length(); i++) {
        if (i != pos && num.charAt(pos) == '0') break;   // no leading zero
        long cur = Long.parseLong(num.substring(pos, i + 1));
        if (pos == 0) {
            dfs(num, target, i + 1, cur, cur, "" + cur, res);
        } else {
            dfs(num, target, i + 1, eval + cur, cur, path + "+" + cur, res);
            dfs(num, target, i + 1, eval - cur, -cur, path + "-" + cur, res);
            dfs(num, target, i + 1, eval - prev + prev * cur, prev * cur,
                path + "*" + cur, res);
        }
    }
}

public List<String> removeInvalidParentheses(String s) {
    int rmL = 0, rmR = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') rmL++;
        else if (c == ')') { if (rmL > 0) rmL--; else rmR++; }
    }
    Set<String> res = new HashSet<>();
    dfs(s, 0, rmL, rmR, res);
    return new ArrayList<>(res);
}

private void dfs(String s, int start, int rmL, int rmR, Set<String> res) {
    if (rmL == 0 && rmR == 0) {
        if (isValid(s)) res.add(s);
        return;
    }
    for (int i = start; i < s.length(); i++) {
        if (i > start && s.charAt(i) == s.charAt(i - 1)) continue;  // skip run duplicates
        char c = s.charAt(i);
        if (c != '(' && c != ')') continue;
        String next = s.substring(0, i) + s.substring(i + 1);
        if (rmR > 0 && c == ')') dfs(next, i, rmL, rmR - 1, res);
        else if (rmL > 0 && c == '(') dfs(next, i, rmL - 1, rmR, res);
    }
}

private boolean isValid(String s) {
    int bal = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') bal++;
        else if (c == ')' && --bal < 0) return false;
    }
    return bal == 0;
}

public boolean canPartitionKSubsets(int[] nums, int k) {
    int sum = 0;
    for (int x : nums) sum += x;
    if (sum % k != 0) return false;
    int target = sum / k;
    Arrays.sort(nums);
    if (nums[nums.length - 1] > target) return false;
    boolean[] used = new boolean[nums.length];
    return backtrack(nums, used, nums.length - 1, k, 0, target);
}

private boolean backtrack(int[] nums, boolean[] used, int idx, int k, int cur, int target) {
    if (k == 0) return true;
    if (cur == target) return backtrack(nums, used, nums.length - 1, k - 1, 0, target);
    for (int i = idx; i >= 0; i--) {
        if (used[i] || cur + nums[i] > target) continue;
        used[i] = true;
        if (backtrack(nums, used, i - 1, k, cur + nums[i], target)) return true;
        used[i] = false;
        if (cur == 0) return false;                       // first item of bucket failed
        while (i > 0 && nums[i - 1] == nums[i]) i--;       // skip duplicates
    }
    return false;
}

public List<String> letterCombinations(String digits) {
    List<String> res = new ArrayList<>();
    if (digits == null || digits.isEmpty()) return res;
    String[] map = {"", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"};
    build(digits, 0, map, new StringBuilder(), res);
    return res;
}
private void build(String digits, int pos, String[] map, StringBuilder sb, List<String> res) {
    if (pos == digits.length()) { res.add(sb.toString()); return; }
    String letters = map[digits.charAt(pos) - '0'];
    for (int i = 0; i < letters.length(); i++) {
        sb.append(letters.charAt(i));
        build(digits, pos + 1, map, sb, res);
        sb.deleteCharAt(sb.length() - 1);
    }
}

public List<String> restoreIpAddresses(String s) {
    List<String> res = new ArrayList<>();
    dfs(s, 0, 0, new StringBuilder(), res);
    return res;
}
private void dfs(String s, int start, int parts, StringBuilder cur, List<String> res) {
    if (parts == 4) {
        if (start == s.length()) res.add(cur.substring(0, cur.length() - 1)); // drop trailing dot
        return;
    }
    for (int len = 1; len <= 3 && start + len <= s.length(); len++) {
        String seg = s.substring(start, start + len);
        if ((seg.length() > 1 && seg.charAt(0) == '0') || Integer.parseInt(seg) > 255) break;
        int mark = cur.length();
        cur.append(seg).append('.');
        dfs(s, start + len, parts + 1, cur, res);
        cur.setLength(mark);
    }
}

public boolean makesquare(int[] matchsticks) {
    if (matchsticks.length < 4) return false;
    int sum = 0;
    for (int x : matchsticks) sum += x;
    if (sum % 4 != 0) return false;
    int side = sum / 4;
    Arrays.sort(matchsticks);
    if (matchsticks[matchsticks.length - 1] > side) return false;
    boolean[] used = new boolean[matchsticks.length];
    return dfs(matchsticks, used, matchsticks.length - 1, 4, 0, side);
}

private boolean dfs(int[] m, boolean[] used, int idx, int k, int cur, int side) {
    if (k == 0) return true;
    if (cur == side) return dfs(m, used, m.length - 1, k - 1, 0, side);
    for (int i = idx; i >= 0; i--) {
        if (used[i] || cur + m[i] > side) continue;
        used[i] = true;
        if (dfs(m, used, i - 1, k, cur + m[i], side)) return true;
        used[i] = false;
        if (cur == 0) return false;                  // first stick of side failed
        while (i > 0 && m[i - 1] == m[i]) i--;        // skip duplicates
    }
    return false;
}
